mapper.select:
SELECT u.user_id as userId, u.email, u.nickname, u.status, u.login_type as loginType, u.last_login_at as lastLoginAt, u.created_at as createdAt, r.role_code as roleName, (SELECT COUNT(*) FROM CHAT_ROOM cr JOIN EXCLUSIVE e2 ON cr.exclusive_id = e2.exclusive_id WHERE e2.user_id = u.user_id) as conversationCount, 0 as activityScore FROM USER u LEFT JOIN USER_ROLE ur ON u.user_id = ur.user_id LEFT JOIN ROLE r ON ur.role_id = r.role_id
AND (u.nickname LIKE CONCAT('%', #{keyword}, '%') OR u.email LIKE CONCAT('%', #{keyword}, '%'))
AND r.role_code = #{role}
AND u.status = #{status}
ORDER BY u.created_at DESC

