mapper.select:
SELECT s.support_id as supportId, s.user_id as userId, u.nickname as userNickname, s.title, s.content, s.status, s.created_at as createdAt, sr.reason_name as reasonName, sr.reason_type as reasonType, sr.target_type as targetType, sa.content as answerContent, au.nickname as answerAdminNickname, sa.created_at as answerCreatedAt FROM SUPPORT s JOIN USER u ON s.user_id = u.user_id JOIN SUPPORT_REASON sr ON s.support_reason_id = sr.support_reason_id LEFT JOIN SUPPORT_ANSWER sa ON sa.answer_id = ( SELECT sa2.answer_id FROM SUPPORT_ANSWER sa2 WHERE sa2.support_id = s.support_id ORDER BY sa2.created_at DESC, sa2.answer_id DESC LIMIT 1 ) LEFT JOIN USER au ON sa.admin_user_id = au.user_id
AND s.status = #{status}
ORDER BY s.created_at DESC
